import{r as e}from"./index-DAWIsfs8.js";var t={listarTodos:async()=>{try{let t=await e.get(`/seguimentos`);return Array.isArray(t.data)?t.data:[]}catch(e){throw e}},criar:async t=>{try{return(await e.post(`/seguimentos`,t)).data}catch(e){throw e}},atualizar:async(t,n)=>{try{return(await e.put(`/seguimentos/update`,{idSeguimento:t,nome:n.nome||n})).data}catch(e){throw e}},inativarReativar:async t=>{try{return(await e.put(`/seguimentos/inativaReativa/${t}`)).data}catch(e){throw e}},excluir:async t=>{try{return(await e.delete(`/seguimentos/delete/${t}`)).data}catch(e){throw e}},contar:async()=>{try{return(await e.get(`/seguimentos/contar`)).data}catch(e){throw e}}};export{t};